pragma solidity ^0.8.19;
// SPDX-License-Identifier: AGPL-3.0-or-later
// Origami (common/access/OrigamiElevatedAccessBase.sol)

import { IOrigamiElevatedAccess } from "contracts/interfaces/common/access/IOrigamiElevatedAccess.sol";
import { CommonEventsAndErrors } from "contracts/libraries/CommonEventsAndErrors.sol";

/**
 * @notice Inherit to add Owner roles for DAO elevated access.
 */ 
abstract contract OrigamiElevatedAccessBase is IOrigamiElevatedAccess {
    /**
     * @notice The address of the current owner.
     */ 
    address public override owner;

    /**
     * @notice Explicit approval for an address to execute a function.
     * allowedCaller => function selector => true/false
     */
    mapping(address => mapping(bytes4 => bool)) public override explicitFunctionAccess;

    /// @dev Track proposed owner
    address private _proposedNewOwner;

    /// @dev propose this as the new owner before revoking, for 2 step approval
    address private constant PROPOSED_DEAD_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    function _init(address initialOwner) internal {
        if (owner != address(0)) revert CommonEventsAndErrors.InvalidAccess();
        if (initialOwner == address(0)) revert CommonEventsAndErrors.InvalidAddress(address(0));
        owner = initialOwner;
    }

    /**
     * @notice Revoke ownership. 
     * @dev To enforce a two-step revoke, it must first propose to 0x000...dEaD prior to calling.
     * This cannot be undone.
     */
    function revokeOwnership() external override onlyElevatedAccess {
        if (_proposedNewOwner != PROPOSED_DEAD_ADDRESS) revert CommonEventsAndErrors.InvalidAddress(_proposedNewOwner);

        emit NewOwnerAccepted(owner, address(0));
        owner = address(0);
    }

    /**
     * @notice Proposes a new Owner.
     * Can only be called by the current owner
     */
    function proposeNewOwner(address account) external override onlyElevatedAccess {
        if (account == address(0)) revert CommonEventsAndErrors.InvalidAddress(account);
        emit NewOwnerProposed(owner, _proposedNewOwner, account);
        _proposedNewOwner = account;
    }

    /**
     * @notice Caller accepts the role as new Owner.
     * Can only be called by the proposed owner
     */
    function acceptOwner() public virtual override {
        if (msg.sender != _proposedNewOwner) revert CommonEventsAndErrors.InvalidAccess();

        emit NewOwnerAccepted(owner, msg.sender);
        owner = msg.sender;
        delete _proposedNewOwner;
    }

    /**
     * @notice Grant `allowedCaller` the rights to call the function selectors in the access list.
     * @dev fnSelector == bytes4(keccak256("fn(argType1,argType2,...)"))
     */
    function setExplicitAccess(address allowedCaller, ExplicitAccess[] calldata access) external override onlyElevatedAccess {
        if (allowedCaller == address(0)) revert CommonEventsAndErrors.InvalidAddress(allowedCaller);
        ExplicitAccess memory _access;
        for (uint256 i; i < access.length; ++i) {
            _access = access[i];
            emit ExplicitAccessSet(allowedCaller, _access.fnSelector, _access.allowed);
            explicitFunctionAccess[allowedCaller][_access.fnSelector] = _access.allowed;
        }
    }

    function isElevatedAccess(address caller, bytes4 fnSelector) internal view returns (bool) {
        return (
            caller == owner || 
            explicitFunctionAccess[caller][fnSelector]
        );
    }

    /**
     * @notice The owner is allowed to call, or if explicit access has been given to the caller.
     * @dev Important: Only for use when called from an *external* contract. 
     * If a function with this modifier is called internally then the `msg.sig` 
     * will still refer to the top level externally called function.
     */
    modifier onlyElevatedAccess() {
        if (!isElevatedAccess(msg.sender, msg.sig)) revert CommonEventsAndErrors.InvalidAccess();
        _;
    }
}

contracts/common/OrigamiErc4626.sol.content:
pragma solidity ^0.8.19;
// SPDX-License-Identifier: AGPL-3.0-or-later
// Origami (common/OrigamiErc4626.sol)

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { EIP712 } from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import { ECDSA } from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import { IERC4626 } from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import { IERC165 } from "@openzeppelin/contracts/interfaces/IERC165.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import { IOrigamiErc4626 } from "contracts/interfaces/common/IOrigamiErc4626.sol";
import { CommonEventsAndErrors } from "contracts/libraries/CommonEventsAndErrors.sol";
import { OrigamiElevatedAccess } from "contracts/common/access/OrigamiElevatedAccess.sol";
import { OrigamiMath } from "contracts/libraries/OrigamiMath.sol";

import { ReentrancyGuard } from "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title Origami ERC-4626
 * @notice A fork of the openzeppelin ERC-4626, with:
 *  - `_decimalsOffset()` set to zero (OZ defaults to zero anyway)
 *  - Always has decimals() of 18dp (rather than using the underlying asset)
 *  - Deposit and Withdraw fees, which are taken from the _shares_ of the user,
 *    benefiting the existing vault holders.
 *  - Permit support
 *  - IERC165 support
 *  - Reentrancy guard on deposit/mint/withdraw/redeem
 *  - maxRedeem & maxWithdraw for address(0) returns the total vault capacity (given any caps within the implementation) 
 *    which can be withdrawn/redeemed (rather than always returning zero)
 * 
 * For the reference implementation, see:
 *  - https://github.com/OpenZeppelin/openzeppelin-contracts/blob/cae60c595b37b1e7ed7dd50ad0257387ec07c0cf/contracts/token/ERC20/extensions/ERC4626.sol
 *  - https://github.com/OpenZeppelin/openzeppelin-contracts/blob/cae60c595b37b1e7ed7dd50ad0257387ec07c0cf/contracts/token/ERC20/extensions/ERC20Permit.sol
 */
contract OrigamiErc4626 is 
    ERC20, 
    IERC4626,
    EIP712,
    ReentrancyGuard,
    OrigamiElevatedAccess,
    IOrigamiErc4626
{
    using SafeERC20 for IERC20;
    using OrigamiMath for uint256;

    // Note the `_maxTotalSupply` is initially set to zero.
    // It is first set upon elevated access calling `seedDeposit()`
    uint256 private _maxTotalSupply;

    bytes32 private constant PERMIT_TYPEHASH =
        keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");

    IERC20 internal immutable _asset;

    mapping(address account => uint256) private _nonces;

    uint8 private constant DECIMALS = 18;

    /// @dev The scalar to convert from `asset` decimals to 18 decimals
    uint256 private immutable _assetsToSharesScalar;

    constructor(
        address initialOwner_,
        string memory name_,
        string memory symbol_,
        IERC20 asset_
    ) 
        OrigamiElevatedAccess(initialOwner_)
        ERC20(name_, symbol_)
        EIP712(name_, "1") 
    {
        uint8 _underlyingDecimals = IERC20Metadata(address(asset_)).decimals();

        // Only allow <= 18 decimal places in the underlying
        // This satisfies the virtual offset requirement where:
        // > Said otherwise, we use more decimal places to represent the shares than the underlying token does to represent the assets.
        // https://docs.openzeppelin.com/contracts/4.x/erc4626#defending_with_a_virtual_offset
        if (_underlyingDecimals > DECIMALS) revert CommonEventsAndErrors.InvalidToken(address(asset_));
        _assetsToSharesScalar = 10 ** (DECIMALS - _underlyingDecimals);

        _asset = asset_;
    }

    /// @inheritdoc IOrigamiErc4626
    function setMaxTotalSupply(uint256 maxTotalSupply_) public virtual override onlyElevatedAccess {
        // Cannot set if the totalSupply is zero - seedDeposit should be used first
        if (totalSupply() == 0) revert CommonEventsAndErrors.InvalidParam();
        _maxTotalSupply = maxTotalSupply_;
        emit MaxTotalSupplySet(maxTotalSupply_);
    }

    /// @inheritdoc IOrigamiErc4626
    function seedDeposit(
        uint256 assets, 
        address receiver, 
        uint256 maxTotalSupply_
    ) external override onlyElevatedAccess returns (uint256 shares) {
        // Only to be used for the first deposit
        if (totalSupply() != 0) revert CommonEventsAndErrors.InvalidParam();
        if (assets == 0) revert CommonEventsAndErrors.ExpectedNonZero();

        // The new maxTotalSupply needs to be at least the size of the
        // new shares minted, or the deposit() will revert.
        _maxTotalSupply = maxTotalSupply_;
        emit MaxTotalSupplySet(maxTotalSupply_);
        return deposit(assets, receiver);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                       EXTERNAL ERC20                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @inheritdoc IERC20Metadata
    function decimals() public view virtual override(IERC20Metadata, ERC20) returns (uint8) {
        return DECIMALS;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                      EXTERNAL ERC4626                      */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @inheritdoc IERC4626
    function asset() public view virtual override returns (address) {
        return address(_asset);
    }

    /// @inheritdoc IERC4626
    function totalAssets() public view virtual override returns (uint256) {
        return _asset.balanceOf(address(this));
    }

    /// @inheritdoc IERC4626
    function convertToShares(uint256 assets) public view virtual override returns (uint256) {
        return _convertToShares(assets, OrigamiMath.Rounding.ROUND_DOWN);
    }

    /// @inheritdoc IERC4626
    function convertToAssets(uint256 shares) public view virtual override returns (uint256) {
        return _convertToAssets(shares, OrigamiMath.Rounding.ROUND_DOWN);
    }

    /// @inheritdoc IERC4626
    function maxDeposit(address /*receiver*/) public override view returns (uint256 maxAssets) {
        return _maxDeposit(depositFeeBps());
    }

    /// @inheritdoc IERC4626
    function maxMint(address /*receiver*/) public override view returns (uint256 maxShares) {
        uint256 maxTotalSupply_ = maxTotalSupply();
        if (maxTotalSupply_ == type(uint256).max) return type(uint256).max;

        uint256 _totalSupply = totalSupply();
        if (_totalSupply > maxTotalSupply_) return 0;

        unchecked {
            maxShares = maxTotalSupply_ - _totalSupply;
        }
    }

    /// @inheritdoc IERC4626
    function maxWithdraw(address sharesOwner) public override view returns (uint256 maxAssets) {
        return _maxWithdraw(sharesOwner, withdrawalFeeBps());
    }

    /// @inheritdoc IERC4626
    function maxRedeem(address sharesOwner) public override view returns (uint256 maxShares) {
        return _maxRedeem(sharesOwner);
    }

    /// @inheritdoc IERC4626
    function previewDeposit(uint256 assets) public view virtual override returns (uint256 shares) {
        (shares,) = _previewDeposit(assets, depositFeeBps());
    }

    /// @inheritdoc IERC4626
    function previewMint(uint256 shares) public view virtual override returns (uint256 assets) {
        (assets,) = _previewMint(shares, depositFeeBps());
    }

    /// @inheritdoc IERC4626
    function previewWithdraw(uint256 assets) public view virtual override returns (uint256 shares) {
        (shares,) = _previewWithdraw(assets, withdrawalFeeBps());
    }

    /// @inheritdoc IERC4626
    function previewRedeem(uint256 shares) public view virtual override returns (uint256 assets) {
        (assets,) = _previewRedeem(shares, withdrawalFeeBps());
    }

    /// @inheritdoc IERC4626
    function deposit(
        uint256 assets, 
        address receiver
    ) public virtual override nonReentrant returns (uint256) {
        uint256 feeBps = depositFeeBps();
        uint256 maxAssets = _maxDeposit(feeBps);
        if (assets > maxAssets) {
            revert ERC4626ExceededMaxDeposit(receiver, assets, maxAssets);
        }

        (uint256 shares, uint256 shareFeesTaken) = _previewDeposit(assets, feeBps);
        if (shareFeesTaken > 0) {
            emit InKindFees(FeeType.DEPOSIT_FEE, feeBps, shareFeesTaken);
        }

        _deposit(_msgSender(), receiver, assets, shares);

        return shares;
    }

    /// @inheritdoc IERC4626
    function mint(
        uint256 shares, 
        address receiver
    ) public virtual override nonReentrant returns (uint256) {
        uint256 maxShares = maxMint(receiver);
        if (shares > maxShares) {
            revert ERC4626ExceededMaxMint(receiver, shares, maxShares);
        }

        uint256 feeBps = depositFeeBps();
        (uint256 assets, uint256 shareFeesTaken) = _previewMint(shares, feeBps);
        if (shareFeesTaken > 0) {
            emit InKindFees(FeeType.DEPOSIT_FEE, feeBps, shareFeesTaken);
        }

        _deposit(_msgSender(), receiver, assets, shares);

        return assets;
    }

    /// @inheritdoc IERC4626
    function withdraw(
        uint256 assets, 
        address receiver, 
        address sharesOwner
    ) public virtual override nonReentrant returns (uint256) {
        uint256 feeBps = withdrawalFeeBps();
        uint256 maxAssets = _maxWithdraw(sharesOwner, feeBps);
        if (assets > maxAssets) {
            revert ERC4626ExceededMaxWithdraw(sharesOwner, assets, maxAssets);
        }

        (uint256 shares, uint256 shareFeesTaken) = _previewWithdraw(assets, feeBps);
        if (shareFeesTaken > 0) {
            emit InKindFees(FeeType.WITHDRAWAL_FEE, feeBps, shareFeesTaken);
        }

        _withdraw(_msgSender(), receiver, sharesOwner, assets, shares);

        return shares;
    }

    /// @inheritdoc IERC4626
    function redeem(
        uint256 shares, 
        address receiver, 
        address sharesOwner
    ) public virtual override nonReentrant returns (uint256) {
        uint256 feeBps = withdrawalFeeBps();
        uint256 maxShares = _maxRedeem(sharesOwner);
        if (shares > maxShares) {
            revert ERC4626ExceededMaxRedeem(sharesOwner, shares, maxShares);
        }

        (uint256 assets, uint256 shareFeesTaken) = _previewRedeem(shares, feeBps);
        if (shareFeesTaken > 0) {
            emit InKindFees(FeeType.WITHDRAWAL_FEE, feeBps, shareFeesTaken);
        }

        _withdraw(_msgSender(), receiver, sharesOwner, assets, shares);

        return assets;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*              EXT. IMPLEMENTATIONS TO OVERRIDE              */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/


    /// @inheritdoc IOrigamiErc4626
    function depositFeeBps() public virtual override view returns (uint256) {
        return 0;
    }

    /// @inheritdoc IOrigamiErc4626
    function withdrawalFeeBps() public virtual override view returns (uint256) {
        return 0;
    }

    /// @inheritdoc IOrigamiErc4626
    function maxTotalSupply() public virtual override view returns (uint256) {
        return _maxTotalSupply;
    }

    /// @inheritdoc IOrigamiErc4626
    function areDepositsPaused() public virtual override view returns (bool) {
        return false;
    }

    /// @inheritdoc IOrigamiErc4626
    function areWithdrawalsPaused() public virtual override view returns (bool) {
        return false;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                   EXTERNAL ERC20Permit                     */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /**
     * @inheritdoc IERC20Permit
     */
    function permit(
        address sharesOwner,
        address spender,
        uint256 value,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) public override {
        if (block.timestamp > deadline) {
            revert ERC2612ExpiredSignature(deadline);
        }

        bytes32 structHash = keccak256(abi.encode(PERMIT_TYPEHASH, sharesOwner, spender, value, _useNonce(sharesOwner), deadline));

        bytes32 hash = _hashTypedDataV4(structHash);

        address signer = ECDSA.recover(hash, v, r, s);
        if (signer != sharesOwner) {
            revert ERC2612InvalidSigner(signer, sharesOwner);
        }

        _approve(sharesOwner, spender, value);
    }

    /// @inheritdoc IERC20Permit
    function nonces(address sharesOwner) public override view returns (uint256) {
        return _nonces[sharesOwner];
    }

    /// @inheritdoc IERC20Permit
    // solhint-disable-next-line func-name-mixedcase
    function DOMAIN_SEPARATOR() external override view virtual returns (bytes32) {
        return _domainSeparatorV4();
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                      EXTERNAL ERC165                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @inheritdoc IERC165
    function supportsInterface(bytes4 interfaceId) public virtual override pure returns (bool) {
        return interfaceId == type(IERC4626).interfaceId 
            || interfaceId == type(IERC20Permit).interfaceId
            || interfaceId == type(EIP712).interfaceId
            || interfaceId == type(IERC165).interfaceId;
    }

    /**
     * @notice Recover any token other than the underlying erc4626 asset.
     * @param token Token to recover
     * @param to Recipient address
     * @param amount Amount to recover
     */
    function recoverToken(address token, address to, uint256 amount) external virtual onlyElevatedAccess {
        if (token == asset()) revert CommonEventsAndErrors.InvalidToken(token);

        emit CommonEventsAndErrors.TokenRecovered(to, token, amount);
        IERC20(token).safeTransfer(to, amount);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                      INTERNAL ERC4626                      */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /**
     * @dev Calculate the max number of assets which can be deposited given the available shares
     * under the maxTotalSupply()
     * This may revert with an overflow for very extreme/unrealistic cases of either a maxTotalSupply
     * which is close to but not exactly type(uint256).max, or an extremely unbalanced share price.
     */
    function _maxDeposit(uint256 feeBps) internal view returns (uint256 maxAssets) {
        uint256 maxTotalSupply_ = maxTotalSupply();
        if (maxTotalSupply_ == type(uint256).max) return type(uint256).max;

        uint256 _totalSupply = totalSupply();
        if (_totalSupply > maxTotalSupply_) return 0;

        uint256 availableShares;
        unchecked {
            availableShares = maxTotalSupply_ - _totalSupply;
        }

        return _convertToAssets(
            availableShares.inverseSubtractBps(feeBps, OrigamiMath.Rounding.ROUND_UP),
            OrigamiMath.Rounding.ROUND_UP
        );
    }

    /**
     * @dev Calculate the max number of assets which can be withdrawn given the number of shares
     * owned by `sharesOwner`
     * May be overridden to enforce other constraints, such as current assets available to withdraw
     * from the underlying asset deployment
     */
    function _maxWithdraw(
        address sharesOwner, 
        uint256 feeBps
    ) internal virtual view returns (uint256 maxAssets) {
        if (sharesOwner == address(0)) return type(uint256).max;

        uint256 shares = balanceOf(sharesOwner);
        // Withdrawal fees are taken from the shares the user redeems
        (shares,) = shares.splitSubtractBps(feeBps, OrigamiMath.Rounding.ROUND_DOWN);
        return _convertToAssets(shares, OrigamiMath.Rounding.ROUND_DOWN);
    }

    /**
     * @dev Calculate the max number of shares which can be redeemed given the number of shares
     * owned by `sharesOwner`
     * May be overridden to enforce other constraints, such as current assets available to withdraw
     * from the underlying asset deployment
     */
    function _maxRedeem(
        address sharesOwner
    ) internal virtual view returns (uint256 maxShares) {
        return sharesOwner == address(0)
            ? type(uint256).max
            : balanceOf(sharesOwner);
    }

    function _previewDeposit(uint256 assets, uint256 feeBps) internal virtual view returns (
        uint256 shares,
        uint256 shareFeesTaken
    ) {
        shares = _convertToShares(assets, OrigamiMath.Rounding.ROUND_DOWN);

        // Deposit fees are taken from the shares in kind
        (shares, shareFeesTaken) = shares.splitSubtractBps(feeBps, OrigamiMath.Rounding.ROUND_DOWN);
    }

    function _previewMint(uint256 shares, uint256 feeBps) internal virtual view returns (
        uint256 assets,
        uint256 shareFeesTaken
    ) {
        // Deposit fees are taken from the shares the user would otherwise receive
        // so calculate the amount of shares required before fees are taken.
        uint256 sharesPlusFees = shares.inverseSubtractBps(feeBps, OrigamiMath.Rounding.ROUND_UP);
        unchecked {
            shareFeesTaken = sharesPlusFees - shares;
        }

        assets = _convertToAssets(sharesPlusFees, OrigamiMath.Rounding.ROUND_UP);
    }

    function _previewWithdraw(uint256 assets, uint256 feeBps) internal view returns (
        uint256 shares,
        uint256 shareFeesTaken
    ) {
        uint256 sharesExcludingFees = _convertToShares(assets, OrigamiMath.Rounding.ROUND_UP);
        // Withdrawal fees are taken from the shares the user redeems
        // so calculate the amount of shares required before fees are taken.
        shares = sharesExcludingFees.inverseSubtractBps(feeBps, OrigamiMath.Rounding.ROUND_UP);
        unchecked {
            shareFeesTaken = shares - sharesExcludingFees;
        }
    }

    function _previewRedeem(uint256 shares, uint256 feeBps) internal view returns (
        uint256 assets,
        uint256 shareFeesTaken
    ) {
        (shares, shareFeesTaken) = shares.splitSubtractBps(feeBps, OrigamiMath.Rounding.ROUND_DOWN);
        assets = _convertToAssets(shares, OrigamiMath.Rounding.ROUND_DOWN);
    }

    /**
     * @dev Internal conversion function (from assets to shares) with support for rounding direction.
     */
    function _convertToShares(uint256 assets, OrigamiMath.Rounding rounding) internal view virtual returns (uint256) {
        return assets.mulDiv(totalSupply() + _assetsToSharesScalar, totalAssets() + 1, rounding);
    }

    /**
     * @dev Internal conversion function (from shares to assets) with support for rounding direction.
     */
    function _convertToAssets(uint256 shares, OrigamiMath.Rounding rounding) internal view virtual returns (uint256) {
        return shares.mulDiv(totalAssets() + 1, totalSupply() + _assetsToSharesScalar, rounding);
    }

    /**
     * @dev Deposit/mint common workflow.
     */
    function _deposit(address caller, address receiver, uint256 assets, uint256 shares) internal virtual {
        if (areDepositsPaused()) revert CommonEventsAndErrors.IsPaused();

        _depositHook(caller, assets);

        _mint(receiver, shares);

        emit Deposit(caller, receiver, assets, shares);
    }

    /**
     * @dev A hook for the implementation to do something with the deposited assets
     */
    function _depositHook(address caller, uint256 assets) internal virtual {
        // The default implementation assumes the assets are just pulled into this contract.
        SafeERC20.safeTransferFrom(_asset, caller, address(this), assets);
    }

    /**
     * @dev Withdraw/redeem common workflow.
     */
    function _withdraw(
        address caller,
        address receiver,
        address sharesOwner,
        uint256 assets,
        uint256 shares
    ) internal virtual {
        if (receiver == address(0)) revert CommonEventsAndErrors.InvalidAddress(receiver);
        if (areWithdrawalsPaused()) revert CommonEventsAndErrors.IsPaused();

        if (caller != sharesOwner) {
            _spendAllowance(sharesOwner, caller, shares);
        }

        // If _asset is ERC777, `transfer` can trigger a reentrancy AFTER the transfer happens through the
        // `tokensReceived` hook. On the other hand, the `tokensToSend` hook, that is triggered before the transfer,
        // calls the vault, which is assumed not malicious.
        //
        // Conclusion: we need to do the transfer after the burn so that any reentrancy would happen after the
        // shares are burned and after the assets are transferred, which is a valid state.
        _burn(sharesOwner, shares);

        // If the vault has been fully exited, then reset the maxTotalSupply to zero, as if it were newly created.
        if (totalSupply() == 0) _maxTotalSupply = 0;

        _withdrawHook(assets, receiver);

        emit Withdraw(caller, receiver, sharesOwner, assets, shares);
    }

    /**
     * @dev A hook for the implementation to pull and send assets to the receiver
     */
    function _withdrawHook(
        uint256 assets,
        address receiver
    ) internal virtual {
        // The default implementation assumes the assets are just sitting in this contract.
        SafeERC20.safeTransfer(_asset, receiver, assets);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    INTERNAL ERC20Permit                    */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /**
     * @dev Consumes a nonce.
     * Returns the current value and increments nonce.
     */
    function _useNonce(address sharesOwner) internal returns (uint256) {
        // For each account, the nonce has an initial value of 0, can only be incremented by one, and cannot be
        // decremented or reset. This guarantees that the nonce never overflows.
        unchecked {
            // It is important to do x++ and not ++x here.
            return _nonces[sharesOwner]++;
        }
    }
}

contracts/interfaces/common/access/IOrig.content:
pragma solidity ^0.8.4;
// SPDX-License-Identifier: AGPL-3.0-or-later
// Origami (interfaces/common/access/IOrigamiElevatedAccess.sol)

/**
 * @notice Inherit to add Owner roles for DAO elevated access.
 */ 
interface IOrigamiElevatedAccess {
    event ExplicitAccessSet(address indexed account, bytes4 indexed fnSelector, bool indexed value);

    event NewOwnerProposed(address indexed oldOwner, address indexed oldProposedOwner, address indexed newProposedOwner);
    event NewOwnerAccepted(address indexed oldOwner, address indexed newOwner);

    struct ExplicitAccess {
        bytes4 fnSelector;
        bool allowed;
    }

    /**
     * @notice The address of the current owner.
     */ 
    function owner() external view returns (address);

    /**
     * @notice Explicit approval for an address to execute a function.
     * allowedCaller => function selector => true/false
     */
    function explicitFunctionAccess(address contractAddr, bytes4 functionSelector) external view returns (bool);

    /**
     * @notice Revoke ownership. Be very certain before calling this, as no
     * further elevated access can be called.
     */
    function revokeOwnership() external;

    /**
     * @notice Proposes a new Owner.
     * Can only be called by the current owner
     */
    function proposeNewOwner(address account) external;

    /**
     * @notice Caller accepts the role as new Owner.
     * Can only be called by the proposed owner
     */
    function acceptOwner() external;

    /**
     * @notice Grant `allowedCaller` the rights to call the function selectors in the access list.
     * @dev fnSelector == bytes4(keccak256("fn(argType1,argType2,...)"))
     */
    function setExplicitAccess(address allowedCaller, ExplicitAccess[] calldata access) external;
}

contracts/interfaces/common/IOrigamiErc4.content:
pragma solidity ^0.8.4;
// SPDX-License-Identifier: AGPL-3.0-or-later
// Origami (interfaces/common/IOrigamiErc4626.sol)

import { IERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import { IERC5267 } from "@openzeppelin/contracts/interfaces/IERC5267.sol";
import { IERC4626 } from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import { IERC165 } from "@openzeppelin/contracts/interfaces/IERC165.sol";

/**
 * @title Origami ERC-4626
 * @notice A fork of the openzeppelin ERC-4626, with:
 *  - `_decimalsOffset()` set to zero (OZ defaults to zero anyway)
 *  - Always has decimals() of 18dp (rather than using the underlying asset)
 *  - Deposit and Withdraw fees, which are taken from the _shares_ of the user,
 *    benefiting the existing vault holders.
 *  - Permit support
 *  - IERC165 support
 *  - Reentrancy guard on deposit/mint/withdraw/redeem
 *  - maxRedeem & maxWithdraw for address(0) returns the total vault capacity (given any caps within the implementation) 
 *    which can be withdrawn/redeemed (rather than always returning zero)
 */
interface IOrigamiErc4626 is 
    IERC4626, 
    IERC20Permit, 
    IERC165, 
    IERC5267
{
    /// @dev Attempted to deposit more assets than the max amount for `receiver`.
    error ERC4626ExceededMaxDeposit(address receiver, uint256 assets, uint256 max);

    /// @dev Attempted to mint more shares than the max amount for `receiver`.
    error ERC4626ExceededMaxMint(address receiver, uint256 shares, uint256 max);

    /// @dev Attempted to withdraw more assets than the max amount for `receiver`.
    error ERC4626ExceededMaxWithdraw(address owner, uint256 assets, uint256 max);

    /// @dev Attempted to redeem more shares than the max amount for `receiver`.
    error ERC4626ExceededMaxRedeem(address owner, uint256 shares, uint256 max);

    /// @dev Permit deadline has expired.
    error ERC2612ExpiredSignature(uint256 deadline);

    /// @dev Mismatched signature.
    error ERC2612InvalidSigner(address signer, address tokensOwner);

    /// @dev What kind of fees - either Deposit or withdrawal
    enum FeeType {
        DEPOSIT_FEE,
        WITHDRAWAL_FEE
    }

    /// @dev Either deposit or withdrawal fees have been updated
    event FeeBpsSet(FeeType feeType, uint256 feeBps);

    /// @dev Either deposit or withdrawal fees have been applied
    event InKindFees(FeeType feeType, uint256 feeBps, uint256 feeAmount);

    /// @dev A client implementation may emit if the max total supply has been changed
    event MaxTotalSupplySet(uint256 maxTotalSupply);

    /// @notice Set the max total supply allowed for this vault
    /// @dev Will revert if the current totalSupply is zero as
    /// `seedDeposit()` needs to be called first
    function setMaxTotalSupply(uint256 maxTotalSupply) external;

    /// @notice Origami protocol seeds the initial deposit
    /// @dev The new maxTotalSupply is set and a trusted deposit
    /// is made
    function seedDeposit(
        uint256 assets,
        address receiver,
        uint256 maxTotalSupply
    ) external returns (uint256 shares);

    /// @notice The current deposit fee in basis points.
    function depositFeeBps() external view returns (uint256);

    /// @notice The current withdrawal fee in basis points.
    function withdrawalFeeBps() external view returns (uint256);

    /// @notice The current maximum total supply of vault tokens.
    function maxTotalSupply() external view returns (uint256);

    /// @notice Whether deposit/mint is currently paused
    function areDepositsPaused() external view returns (bool);

    /// @notice Whether withdrawal/redeem is currently paused
    function areWithdrawalsPaused() external view returns (bool);
}

contracts/interfaces/common/ITokenPrices.content:
pragma solidity ^0.8.4;
// SPDX-License-Identifier: AGPL-3.0-or-later
// Origami (interfaces/common/ITokenPrices.sol)

/// @title Token Prices
/// @notice A utility contract to pull token prices from on-chain.
/// @dev composable functions (uisng encoded function calldata) to build up price formulas
interface ITokenPrices {
    /// @notice How many decimals places are the token prices reported in
    function decimals() external view returns (uint8);

    /// @notice Retrieve the price for a given token.
    /// @dev If not mapped, or an underlying error occurs, FailedPriceLookup will be thrown.
    /// @dev 0x000...0 is the native chain token (ETH/AVAX/etc)
    function tokenPrice(address token) external view returns (uint256 price);

    /// @notice Token address to function calldata for how to lookup the price for this token
    function priceFnCalldata(address token) external view returns (bytes memory fnCalldata);

    /// @notice Retrieve the price for a list of tokens.
    /// @dev If any aren't mapped, or an underlying error occurs, FailedPriceLookup will be thrown.
    /// @dev Not particularly gas efficient - wouldn't recommend to use on-chain
    function tokenPrices(address[] memory tokens) external view returns (uint256[] memory prices);

    /// @notice The set of all mapped tokens
    function mappedTokenAt(uint256 i) external view returns (address token);

    /// @notice The set of all mapped tokens
    function allMappedTokens() external view returns (address[] memory);

    /// @notice The number of mapped tokens
    function numMappedTokens() external view returns (uint256);
}

contracts/interfaces/common/oracle/IOrig.content:
pragma solidity ^0.8.4;
// SPDX-License-Identifier: AGPL-3.0-or-later
// Origami (interfaces/common/oracle/IOrigamiOracle.sol)

import { OrigamiMath } from "contracts/libraries/OrigamiMath.sol";

/**
 * @notice An oracle which returns prices for pairs of assets, where an asset
 * could refer to a token (eg DAI) or a currency (eg USD)
 * Convention is the same as the FX market. Given the DAI/USD pair:
 *   - DAI = Base Asset (LHS of pair)
 *   - USD = Quote Asset (RHS of pair)
 * This price defines how many USD you get if selling 1 DAI
 *
 * Further, an oracle can define two PriceType's:
 *   - SPOT_PRICE: The latest spot price, for example from a chainlink oracle
 *   - HISTORIC_PRICE: An expected (eg 1:1 peg) or calculated historic price (eg TWAP)
 *
 * For assets which do are not tokens (eg USD), an internal address reference will be used
 * since this is for internal purposes only
 */
interface IOrigamiOracle {
    error InvalidPrice(address oracle, int256 price);
    error InvalidOracleData(address oracle);
    error StalePrice(address oracle, uint256 lastUpdatedAt, int256 price);
    error UnknownPriceType(uint8 priceType);
    error BelowMinValidRange(address oracle, uint256 price, uint128 floor);
    error AboveMaxValidRange(address oracle, uint256 price, uint128 ceiling);

    event ValidPriceRangeSet(uint128 validFloor, uint128 validCeiling);

    enum PriceType {
        /// @notice The current spot price of this Oracle
        SPOT_PRICE,

        /// @notice The historic price of this Oracle. 
        /// It may be a fixed expectation (eg DAI/USD would be fixed to 1)
        /// or use a TWAP or some other moving average, etc.
        HISTORIC_PRICE
    }

    /**
     * @dev Wrapped in a struct to remove stack-too-deep constraints
     */
    struct BaseOracleParams {
        string description;
        address baseAssetAddress;
        uint8 baseAssetDecimals;
        address quoteAssetAddress;
        uint8 quoteAssetDecimals;
    }

    /**
     * @notice The address used to reference the baseAsset for amount conversions
     */
    function baseAsset() external view returns (address);

    /**
     * @notice The address used to reference the quoteAsset for amount conversions
     */
    function quoteAsset() external view returns (address);

    /**
     * @notice The number of decimals of precision the price is returned as
     */
    function decimals() external view returns (uint8);

    /**
     * @notice The precision that the cross rate oracle price is returned as: `10^decimals`
     */
    function precision() external view returns (uint256);

    /**
     * @notice When converting from baseAsset<->quoteAsset, the fixed point amounts
     * need to be scaled by this amount.
     */
    function assetScalingFactor() external view returns (uint256);

    /**
     * @notice A human readable description for this oracle
     */
    function description() external view returns (string memory);

    /**
     * @notice Return the latest oracle price, to `decimals` precision
     * @dev This may still revert - eg if deemed stale, div by 0, negative price
     * @param priceType What kind of price - Spot or Historic
     * @param roundingMode Round the price at each intermediate step such that the final price rounds in the specified direction.
     */
    function latestPrice(
        PriceType priceType, 
        OrigamiMath.Rounding roundingMode
    ) external view returns (uint256 price);

    /**
     * @notice Same as `latestPrice()` but for two separate prices from this oracle	
     */
    function latestPrices(
        PriceType priceType1, 
        OrigamiMath.Rounding roundingMode1,
        PriceType priceType2, 
        OrigamiMath.Rounding roundingMode2
    ) external view returns (
        uint256 price1, 
        uint256 price2, 
        address oracleBaseAsset,
        address oracleQuoteAsset
    );

    /**
     * @notice Convert either the baseAsset->quoteAsset or quoteAsset->baseAsset
     * @dev The `fromAssetAmount` needs to be in it's natural fixed point precision (eg USDC=6dp)
     * The `toAssetAmount` will also be returned in it's natural fixed point precision
     */
    function convertAmount(
        address fromAsset,
        uint256 fromAssetAmount,
        PriceType priceType,
        OrigamiMath.Rounding roundingMode
    ) external view returns (uint256 toAssetAmount);

    /**
     * @notice Match whether a pair of assets match the base and quote asset on this oracle, in either order
     */
    function matchAssets(address asset1, address asset2) external view returns (bool);
}

contracts/interfaces/investments/erc4626.content:
pragma solidity ^0.8.4;
// SPDX-License-Identifier: AGPL-3.0-or-later
// Origami (investments/erc4626/IOrigamiDelegated4626Vault.sol)

import { ITokenPrices } from "contracts/interfaces/common/ITokenPrices.sol";
import { IOrigamiErc4626 } from "contracts/interfaces/common/IOrigamiErc4626.sol";

/** 
 * @title Origami Delegated ERC4626 Vault
 * @notice An Origami ERC4626 Vault, which delegates the handling of deposited assets
 * to a manager
 */
interface IOrigamiDelegated4626Vault is IOrigamiErc4626 {
    event TokenPricesSet(address indexed _tokenPrices);
    event ManagerSet(address indexed manager);
    event PerformanceFeeSet(uint256 fee);

    /**
     * @notice Set the helper to calculate current off-chain/subgraph integration
     */
    function setTokenPrices(address tokenPrices) external;

    /**
     * @notice Set the Origami delegated manager 
     */
    function setManager(address manager) external;

    /**
     * @notice The performance fee to Origami treasury
     * Represented in basis points
     */
    function performanceFeeBps() external view returns (uint48);

    /**
     * @notice The helper contract to retrieve Origami USD prices
     * @dev Required for off-chain/subgraph integration
     */
    function tokenPrices() external view returns (ITokenPrices);

    /**
     * @notice The Origami contract managing the application of
     * the deposit tokens into the underlying protocol
     */
    function manager() external view returns (address);
}

pragma solidity ^0.8.4;
// SPDX-License-Identifier: AGPL-3.0-or-later
// Origami (investments/erc4626/IOrigamiDelegated4626VaultManager.sol)

import { IERC165 } from "@openzeppelin/contracts/interfaces/IERC165.sol";
import { IOrigamiDelegated4626Vault } from "contracts/interfaces/investments/erc4626/IOrigamiDelegated4626Vault.sol";
import { DynamicFees } from "contracts/libraries/DynamicFees.sol";

/** 
 * @title Origami Delegated ERC4626 Vault Manager
 * @notice An Origami ERC4626 Vault Manager, which handles the deposited assets from a
 * IOrigamiDelegated4626Vault
 */
interface IOrigamiDelegated4626VaultManager is IERC165 {
    event FeeBpsSet(uint16 depositFeeBps, uint16 withdrawalFeeBps);
    event InKindFees(DynamicFees.FeeType feeType, uint256 feeBps, uint256 feeAmount);
    event FeeCollectorSet(address indexed feeCollector);

    /// @notice Deposit tokens into the underlying protocol
    /// @dev Implementation SHOULD assume the tokens have already been sent to this contract
    /// @param assetsAmount The amount of assets to deposit. Implementation MAY choose to accept 
    /// type(uint256).max as a special value indicating the full balance of the contract
    function deposit(uint256 assetsAmount) external returns (
        uint256 assetsDeposited
    );

    /// @notice Withdraw tokens from the underlying protocol to a given receiver
    /// @dev
    /// - Fails if it can't withdraw that amount
    /// - type(uint256).max is accepted, meaning the entire balance
    function withdraw(
        uint256 assetsAmount,
        address receiver
    ) external returns (uint256 assetsWithdrawn);

    /// @notice The Origami vault this is managing
    function vault() external view returns (IOrigamiDelegated4626Vault);

    /// @notice Returns the address of the underlying token used for the Vault for accounting, depositing, and withdrawing.
    /// @dev
    /// - MUST be an ERC-20 token contract.
    /// - MUST NOT revert.
    function asset() external view returns (address assetTokenAddress);

    /// @notice Returns the total amount of the underlying asset that is “managed” by Vault.
    /// @dev
    /// - SHOULD include any compounding that occurs from yield.
    /// - MUST be inclusive of any fees that are charged against assets in the Vault.
    /// - MUST NOT revert.
    function totalAssets() external view returns (uint256 totalManagedAssets);

    /// @notice Returns the amount of the underlying asset that is not yet allocated to any strategy
    function unallocatedAssets() external view returns (uint256);

    /// @notice The performance fee to the caller (to compensate for gas) and Origami treasury.
    /// @dev Represented in basis points.
    function performanceFeeBps() external view returns (uint16 forCaller, uint16 forOrigami);

    /// @notice Whether deposits and mints are currently paused
    function areDepositsPaused() external view returns (bool);

    /// @notice Whether withdrawals and redemptions are currently paused
    function areWithdrawalsPaused() external view returns (bool);

    /// @notice The current deposit fee in basis points
    function depositFeeBps() external view returns (uint16);

    /// @notice The current withdrawal fee in basis points
    function withdrawalFeeBps() external view returns (uint16);
}

contracts/investments/OrigamiDelegated46.content:
pragma solidity ^0.8.19;
// SPDX-License-Identifier: AGPL-3.0-or-later
// Origami (investments/OrigamiDelegated4626Vault.sol)

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IERC4626 } from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import { IOrigamiDelegated4626Vault } from "contracts/interfaces/investments/erc4626/IOrigamiDelegated4626Vault.sol";
import { IOrigamiDelegated4626VaultManager } from "contracts/interfaces/investments/erc4626/IOrigamiDelegated4626VaultManager.sol";
import { ITokenPrices } from "contracts/interfaces/common/ITokenPrices.sol";
import { IOrigamiErc4626 } from "contracts/interfaces/common/IOrigamiErc4626.sol";
import { OrigamiErc4626 } from "contracts/common/OrigamiErc4626.sol";
import { CommonEventsAndErrors } from "contracts/libraries/CommonEventsAndErrors.sol";

/**
 * @title Origami 4626 Vault that delegates strategy to a manager.
 * @notice Assets are held and managed by the manager. This vault handles simple shares accounting.
 */
contract OrigamiDelegated4626Vault is
    OrigamiErc4626,
    IOrigamiDelegated4626Vault
{
    using SafeERC20 for IERC20;

    /// @inheritdoc IOrigamiDelegated4626Vault
    ITokenPrices public override tokenPrices;

    /// @dev The manager which handles the investment strategy
    IOrigamiDelegated4626VaultManager internal _manager;

    constructor(
        address initialOwner_,
        string memory name_,
        string memory symbol_,
        IERC20 asset_,
        address tokenPrices_
    ) 
        OrigamiErc4626(initialOwner_, name_, symbol_, asset_)
    {
        tokenPrices = ITokenPrices(tokenPrices_);
    }

    /// @inheritdoc IOrigamiDelegated4626Vault
    function setManager(address newManager) external virtual override onlyElevatedAccess {
        if (newManager == address(0)) revert CommonEventsAndErrors.InvalidAddress(address(0));
        emit ManagerSet(newManager);
        _manager = IOrigamiDelegated4626VaultManager(newManager);
    }

    /// @inheritdoc IOrigamiDelegated4626Vault
    function setTokenPrices(address _tokenPrices) external virtual override onlyElevatedAccess {
        if (_tokenPrices == address(0)) revert CommonEventsAndErrors.InvalidAddress(address(0));
        emit TokenPricesSet(_tokenPrices);
        tokenPrices = ITokenPrices(_tokenPrices);
    }

    /**
     * @notice Emit an event from the vault when the performance fees are updated
     */
    function logPerformanceFeesSet(uint256 performanceFees) external virtual {
        if (msg.sender != address(_manager)) revert CommonEventsAndErrors.InvalidAccess();
        emit PerformanceFeeSet(performanceFees);
    }

    /// @inheritdoc IERC4626
    function totalAssets() public view virtual override(IERC4626, OrigamiErc4626) returns (uint256) {
        return _manager.totalAssets();
    }

    /// @inheritdoc IOrigamiErc4626
    function areDepositsPaused() public virtual override(IOrigamiErc4626, OrigamiErc4626) view returns (bool) {
        return _manager.areDepositsPaused();
    }

    /// @inheritdoc IOrigamiErc4626
    function areWithdrawalsPaused() public virtual override(IOrigamiErc4626, OrigamiErc4626) view returns (bool) {
        return _manager.areWithdrawalsPaused();
    }

    /// @inheritdoc IOrigamiDelegated4626Vault
    function manager() external virtual override view returns (address) {
        return address(_manager);
    }

    /// @inheritdoc IOrigamiDelegated4626Vault
    function performanceFeeBps() external virtual override view returns (uint48) {
        // Return the total fee for both the caller (to pay for gas) and origami
        (uint48 callerFeeBps, uint48 origamiFeeBps) = _manager.performanceFeeBps();
        return callerFeeBps + origamiFeeBps; 
    }

    /// @dev Pull freshly deposited assets and deposit into the manager
    function _depositHook(address caller, uint256 assets) internal virtual override {
        SafeERC20.safeTransferFrom(_asset, caller, address(_manager), assets);
        _manager.deposit(assets);
    }

    /// @inheritdoc IOrigamiErc4626
    function depositFeeBps() public view virtual override(IOrigamiErc4626, OrigamiErc4626) returns (uint256) {
        return _manager.depositFeeBps();
    }

    /// @dev Pull assets from the manager which also sends to the receiver
    function _withdrawHook(
        uint256 assets,
        address receiver
    ) internal virtual override {
        _manager.withdraw(assets, receiver);
    }

    /// @inheritdoc IOrigamiErc4626
    function withdrawalFeeBps() public view virtual override(IOrigamiErc4626, OrigamiErc4626) returns (uint256) {
        return _manager.withdrawalFeeBps();
    }
}

